        detailPop.innerHTML='<div class="gpu-popover-title"><span>'+escape(g.node)+' · GPU '+g.id+'</span><span class="muted">'+st+'</span></div><div class="gpu-popover-model">'+escape(g.model||'未知型号')+'</div><div class="gpu-popover-primary"><div class="gpu-popover-kpi"><strong>'+(g.online===false?'—':g.util+'%')+'</strong><span>利用率</span></div><div class="gpu-popover-kpi"><strong>'+(g.online===false?'—':g.used+' / '+g.total+' G')+'</strong><span>显存占用</span></div></div><div class="gpu-popover-aux"><span>功耗 '+(g.power??'—')+'/'+(g.powerLimit??'—')+' W</span><span>温度 '+(g.temp??'—')+'°C</span></div>';
