      const selected=state.clusters[state.target]||[];
      dialog('集群节点','<p class="small muted">通过当前服务器跳转采集节点监控（每行一个节点名，支持 host:port）。请确保当前主机支持 SSH 转发且本机密钥可直接登录各节点。</p><div class="flex" style="margin:12px 0"><button class="button" data-action="discover-cluster">发现 Slurm 节点</button><span class="small muted" id="rw-cluster-status"></span></div><div id="rw-cluster-discovered"></div><label class="form-field">已选节点 / 手动输入<textarea class="input mono" id="rw-cluster-input" rows="5" placeholder="node01\nnode02:22">'+escape(selected.join('\n'))+'</textarea></label><p class="small muted" style="margin-top:8px">最多支持 50 个节点，采样间隔最短 5 秒。</p>','<button class="button" data-action="close-dialog">取消</button><button class="button primary" data-action="save-cluster">应用</button>');
