      const metric=e.target.closest('[data-metric]');if(metric){const m={node:metric.dataset.node,type:metric.dataset.metric};state.metric=state.metric?.node===m.node&&state.metric?.type===m.type?null:m;renderMonitor();remember();return}
      const gpuCell=e.target.closest('[data-gpu-cell]');if(gpuCell){e.stopPropagation();hideDetailPop();const [node,gid]=gpuCell.dataset.gpuCell.split('|'),id=Number(gid);if(!gpuCell.closest('tr')&&state.gpu?.node===node&&state.gpu?.id===id)state.gpu=null;else state.gpu={node,id};renderMonitor();remember();return}
      const gpuRow=e.target.closest('[data-gpu-row]');if(gpuRow){const node=gpuRow.dataset.gpuRow;if(state.gpu?.node===node)state.gpu=null;else{const first=gpus.find(g=>g.node===node);if(!first)return;state.gpu={node,id:first.id}}renderMonitor();remember();return}
      const procSort=e.target.closest('[data-proc-sort]');if(procSort){const k=procSort.dataset.procSort;state.processDirection=state.processSort===k?(state.processDirection==='desc'?'asc':'desc'):(['node','user'].includes(k)?'asc':'desc');state.processSort=k;updateProcessBody();return}
