      if(action==='save-cluster'){const text=overlay.querySelector('#rw-cluster-input').value,checked=[...overlay.querySelectorAll('[data-cluster-node]:checked')].map(x=>x.value),discovered=[...overlay.querySelectorAll('[data-cluster-node]')].map(x=>x.value),manual=text.split(/\s+/).filter(x=>x&&!discovered.includes(x)),items=[...new Set([...manual,...checked])];if(items.length>50||items.some(x=>{const m=/^([A-Za-z0-9][A-Za-z0-9._-]{0,252})(?::([0-9]{1,5}))?$/.exec(x);return !m||!!m[2]&&(Number(m[2])<1||Number(m[2])>65535)})){announce('节点地址无效或超过 50 个');return}const host=state.target;state.clusters[host]=items;saveClusters();syncClusterView();state.metric=null;state.gpu=null;closeDialog();renderMonitor();remember();perform(callApi('cluster.close',{host}),()=>requestPoll(true));return}
      if(action==='members'){if(state.scope==='cluster')showCluster();else showMembers();return}if(action==='close-dialog'){closeDialog();return}if(action==='save-members'){state.members=[...overlay.querySelectorAll('[name=member]:checked')].map(i=>i.value);state.scope='group';state.metric=null;closeDialog();renderMonitor();remember();const selected=[...state.members];perform(Promise.allSettled(selected.map(host=>callApi('hosts.connect',{host}))),()=>requestPoll(true));return}
      if(action==='refresh-monitor'){requestPoll(true);return}if(action==='stop-current-monitor'){state.members=state.members.filter(id=>id!==state.target);state.scope='group';state.metric=null;state.gpu=null;renderMonitor();remember();requestPoll();return}
