      if(action==='parent'){state.pathEditing=false;const path=cwd();setPath(path.slice(0,path.lastIndexOf('/'))||'/');return}if(action==='cd'){state.pathEditing=false;setPath(button.dataset.path||'/');return}if(action==='edit-path'||action==='edit-path-bar'){if(e.target.closest('#rw-inline-path'))return;state.pathEditing=true;renderFiles();return}if(action==='pin-entry'){state.entryDefaults[state.target]=cwd();state.pathEditing=false;renderFiles();announce('已将当前目录设为本对话入口');return}if(action==='clear-selection'){state.selected=null;renderFiles();return}if(action==='file-select'){const f=entries().find(f=>f.name===button.dataset.name);if(f?.dir){setPath(cwd()+'/'+f.name);return}state.selected=button.dataset.name;renderFiles();if(f)previewFile(f.name);return}
      if(action==='preview'){if(state.selected)previewFile(state.selected);return}if(action==='refresh'){loadDirectory();return}if(action==='refresh-preview'){if(state.selected)previewFile(state.selected);return}if(action==='download'){if(state.selected)perform(callApi('files.download',{host:state.target,path:cwd()+'/'+state.selected}),result=>{const bytes=Uint8Array.from(atob(result.base64),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes]));const a=document.createElement('a');a.href=url;a.download=result.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});return}
