      if(action==='create-file'){const name=overlay.querySelector('#rw-new-name').value.trim();if(!name||name.includes('/')||name==='.'||name==='..'||entries().some(f=>f.name===name)){announce('请填写不重复的有效名称');return}const type=overlay.querySelector('#rw-new-type').value;perform(callApi('files.create',{host:state.target,path:cwd()+'/'+name,type}),()=>{closeDialog();loadDirectory()});return}
