      if(action==='job'){state.job=state.job===button.dataset.id?null:button.dataset.id;if(state.job)fetchJobDetail(state.target,state.job);else state.jobDetails=null;renderJobs();return}if(action==='job-log'){const path=button.dataset.path;if(path)previewFile(path.split('/').pop(),path);return}if(action==='clone-job'){const j=jobs.find(x=>x.id===button.dataset.id),d=state.job===button.dataset.id&&state.jobDetails?state.jobDetails:{};if(j){state.draft.name=j.name||state.draft.name;if(j.part)state.draft.part=j.part;if(d.WorkDir||j.workDir)state.draft.workdir=d.WorkDir||j.workDir;const cmd=(d.Command&&d.Command!=='(null)'?d.Command:'')||(j.command&&j.command!=='(null)'?j.command:'');if(cmd)state.draft.command=cmd;const tl=d.TimeLimit||j.timeLimit;if(tl&&/^\d+:\d{2}:\d{2}$/.test(tl))state.draft.time=tl;if(j.nodes>0&&j.gpu>0)state.draft.gpu=Math.max(0,Math.round(j.gpu/j.nodes))}state.wizard=1;renderJobs();return}if(action==='new-job'){if(!partitions.length)perform(callApi('slurm.partitions',{host:state.target}),rows=>{partitions=rows;state.draft.part=rows[0]?.name||'';state.wizard=1;renderJobs()});else{state.draft.part=partitions[0]?.name||state.draft.part;state.wizard=1;renderJobs()}return}if(action==='exit-wizard'){readDraft();state.wizard=0;renderJobs();return}if(action==='next-step'||action==='prev-step'){readDraft();if(!state.draft.name||!state.draft.workdir.startsWith('/')||state.draft.workers<1||state.draft.cpu<1||state.draft.memory<1){announce('请检查任务名称、绝对工作目录和资源数量');return}state.wizard+=action==='next-step'?1:-1;renderJobs();return}
