    function WorkbenchView({ sessionId, openRemotePreview, t, rpc }) {
      const ref = useRef(null)
      useEffect(() => {
        if (!ref.current) return undefined
        return mountWorkbench(ref.current, sessionId, openRemotePreview, t, rpc)
      }, [sessionId, openRemotePreview])
      useEffect(() => { translateWorkbench(ref.current, t) })
      return E('div', { id: 'remote-workbench', ref, role: 'region', 'aria-label': '远程服务器工作台', style: { width: '100%', height: '100%', minHeight: 0 } })
    }

    function FilePreview({ useTabInfo, useResource, t }) {
      const info = useTabInfo()
      const source = useResource(info.tab.navigation.address)
      const doc = source.value || info.tab.navigation.params?.remotePreview
      if (!doc) return E('div', { className: 'remote-preview-state', role: 'status' }, source.status === 'failed' ? t('cannotReadPreview') : t('loadingPreview'))
      return E('section', { className: 'remote-preview' },
        E('div', { className: 'remote-preview-meta' }, doc.target + ' · ' + t('sshUser') + ' · ' + t('readOnly')),
        E('div', { className: 'remote-preview-name' }, doc.name),
        E('div', { className: 'remote-preview-path' }, doc.path),
        E('pre', { className: 'remote-preview-code' }, doc.text))
    }

    function FilePreviewTitle({ useTabInfo, useResource }) {
      const info = useTabInfo()
      const source = useResource(info.tab.navigation.address)
      const doc = source.value || info.tab.navigation.params?.remotePreview
      return E(React.Fragment, null, E('span', { 'aria-hidden': true, className: 'remote-preview-file-icon' }, '▤'), doc?.name || info.tab.title)
    }

